// BAD: Mocking a Value Object and trying to assert business rules on mocks
public class OrderServiceTest {
    @Test
    public void testCalculateTotal() {
        Money mockMoney = mock(Money.class);
        when(mockMoney.getAmount()).thenReturn(BigDecimal.valueOf(100)); // Fragile!
        // Testing nothing of value here
    }
}

// GOOD: Using real Value Objects and Domain models
public class OrderServiceTest {
    @Test
    public void testCalculateTotal() {
        Money price = new Money(BigDecimal.valueOf(50), Currency.USD);
        Order order = new Order(price, 2);

        Money total = order.calculateTotal();

        assertEquals(new Money(BigDecimal.valueOf(100), Currency.USD), total);
    }
}
